import {createHash} from 'node:crypto';
import {prepCanonical,prepId,prepTimestampToken} from './prep-model.mjs';
export const ACTUAL_PREP_DECLARATION='AdditionalUnloggedProduction';
export const actualPrepId=value=>prepId(value)&&value.startsWith('actual-prep-')&&value.length<=96;
export const actualPrepHash=value=>createHash('sha256').update(prepCanonical(value)).digest('hex');
export const actualPrepIntent=input=>({outputInventoryId:input.outputInventoryId,qty:input.qty,reason:input.reason||'',actualProductionDeclaration:ACTUAL_PREP_DECLARATION});
const plain=value=>Boolean(value&&typeof value==='object'&&!Array.isArray(value)&&[Object.prototype,null].includes(Object.getPrototypeOf(value))),keys=(value,list)=>plain(value)&&Object.keys(value).length===list.length&&list.every(key=>Object.hasOwn(value,key));
const text=(value,max)=>typeof value==='string'&&value.trim().length>0&&value.length<=max&&!/[\u0000-\u001f\u007f]/.test(value),signed=value=>typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)<=1e12;
const near=(a,b)=>Math.abs(a-b)<=Math.max(1,Math.abs(b))*Number.EPSILON*8;
export function actualPrepWarnings(plan){return plan.effects.filter(row=>row.role==='ingredient'&&(row.beforeStock<0||row.afterStock<0)).map(row=>({inventoryId:row.id,itemName:row.name,unit:row.unit,beforeStock:row.beforeStock,delta:row.delta,afterStock:row.afterStock}));}
export const actualWarningFingerprint=(operationId,expectedFingerprint,plan)=>actualPrepHash({version:2,kind:'actual-prep-warning-ack',operationId,expectedFingerprint,rows:actualPrepWarnings(plan)});
export const validActualAcknowledgement=(value,fingerprint,required)=>required?keys(value,['warningFingerprint','acknowledged'])&&value.acknowledged===true&&value.warningFingerprint===fingerprint:value===null||value===undefined;
export function assertActualPrepPlan(plan){
 if(!keys(plan,['version','kind','branch','outputInventoryId','outputName','qty','purchaseUnit','outputBaseQuantity','effects','recipe'])||plan.version!==2||plan.kind!=='actual-prep'||!text(plan.branch,128)||/^all$/i.test(plan.branch)||!prepId(plan.outputInventoryId)||!text(plan.outputName,160)||!text(plan.purchaseUnit,40)||typeof plan.qty!=='number'||!Number.isFinite(plan.qty)||plan.qty<=0||plan.qty>1e6||!signed(plan.outputBaseQuantity)||plan.outputBaseQuantity<=0||!Array.isArray(plan.effects)||plan.effects.length<2||plan.effects.length>31||!Array.isArray(plan.recipe)||plan.recipe.length!==plan.effects.length-1)throw Error('Invalid exact actual-prep plan.');
 const ids=new Set(),ingredients=new Map();for(const [index,row]of plan.effects.entries()){
  if(!keys(row,['id','name','branch','unit','beforeStock','beforeUpdateTime','delta','afterStock','role'])||!prepId(row.id)||ids.has(row.id)||row.branch!==plan.branch||!text(row.name,160)||!text(row.unit,40)||!prepTimestampToken(row.beforeUpdateTime)||![row.beforeStock,row.delta,row.afterStock].every(signed)||row.delta===0||!near(row.afterStock-row.beforeStock,row.delta)||row.role!==(index===0?'output':'ingredient')||index===0&&(row.id!==plan.outputInventoryId||row.name!==plan.outputName||row.delta!==plan.outputBaseQuantity||row.delta<=0)||index>0&&(row.id===plan.outputInventoryId||row.delta>=0))throw Error('Invalid actual-prep movement.');ids.add(row.id);if(index>0)ingredients.set(row.id,row);
 }
 const recipes=new Set();for(const row of plan.recipe){const effect=ingredients.get(row?.inventoryId);if(!keys(row,['id','updateTime','inventoryId','quantityPerBatch','unit'])||!prepId(row.id)||recipes.has(row.id)||!prepTimestampToken(row.updateTime)||!effect||row.unit!==effect.unit||typeof row.quantityPerBatch!=='number'||!Number.isFinite(row.quantityPerBatch)||row.quantityPerBatch<=0||row.quantityPerBatch>1e12||!near(row.quantityPerBatch*plan.qty,-effect.delta))throw Error('Invalid actual-prep recipe evidence.');recipes.add(row.id);ingredients.delete(row.inventoryId);}if(ingredients.size)throw Error('Incomplete actual-prep recipe evidence.');return plan;
}
export function validStockWarningRows(rows){return Array.isArray(rows)&&rows.length>=1&&rows.length<=30&&new Set(rows.map(row=>row?.inventoryId)).size===rows.length&&rows.every(row=>keys(row,['inventoryId','itemName','unit','beforeStock','delta','afterStock'])&&prepId(row.inventoryId)&&text(row.itemName,160)&&text(row.unit,40)&&[row.beforeStock,row.delta,row.afterStock].every(signed)&&row.delta<0&&(row.beforeStock<0||row.afterStock<0)&&near(row.afterStock-row.beforeStock,row.delta));}
